# _recipe_write.py — write steering recipe as TOML.
# NEVER DELETE COMMENTS — explain every non-obvious line.
# Update comments with the code; do not strip them.
import datetime


def write_recipe(candidates, out_path):
    """Write steering recipe TOML from contrast candidates."""
    lines = [
        "# Neuron steering recipe — generated by neuron-explorer",
        "# NEVER DELETE COMMENTS — explain every non-obvious line.",
        f'# Generated: {datetime.datetime.now().isoformat()}',
        "",
        "[meta]",
        f'generated = "{datetime.datetime.now().isoformat()}"',
        f"count = {len(candidates)}",
        "",
    ]
    for i, c in enumerate(candidates):
        lines.append(f"[[steer]]")
        lines.append(f"layer = {c['layer']}")                # decoder layer index
        lines.append(f"neuron = {c['neuron']}")              # neuron column index
        lines.append(f"dose = {c['contrast']:.6f}")          # signed steering dose
        sign = "+" if c["contrast"] > 0 else "-"
        lines.append(f'# L{c["layer"]} N{c["neuron"]} {sign}{abs(c["contrast"]):.4f}')
        lines.append("")

    with open(out_path, "w") as f:
        f.write("\n".join(lines))
    return len(candidates)
